<?php
declare(strict_types=1);
namespace App\Services; use App\Core\Database;
final class ReportService { public function expenses(array $f,array $actor):array{$where=['e.status="posted"'];$p=[];if(!\App\Services\Authorization::allows($actor,'finance.view_all')){$where[]='e.user_id=?';$p[]=(int)$actor['id'];}elseif(($f['user_id']??'')!==''){$where[]='e.user_id=?';$p[]=(int)$f['user_id'];}foreach(['category_id','account_id'] as $k){if(($f[$k]??'')!==''){$where[]='e.'.$k.'=?';$p[]=$f[$k];}}if(!empty($f['q'])){$where[]='(e.description LIKE ? OR e.notes LIKE ?)';$p[]='%'.$f['q'].'%';$p[]='%'.$f['q'].'%';}if(!empty($f['from'])){$where[]='e.expense_date>=?';$p[]=$f['from'];}if(!empty($f['to'])){$where[]='e.expense_date<=?';$p[]=$f['to'];}$s=Database::connection()->prepare('SELECT e.expense_date,e.amount,c.name category,ucs.badge,COALESCE(ucs.icon,c.icon) category_icon,COALESCE(ucs.color,c.color) category_color,a.name account,a.type account_type,e.description,u.name user_name FROM expenses e LEFT JOIN categories c ON c.id=e.category_id LEFT JOIN accounts a ON a.id=e.account_id LEFT JOIN users u ON u.id=e.user_id LEFT JOIN user_category_settings ucs ON ucs.user_id=e.user_id AND ucs.category_id=e.category_id WHERE '.implode(' AND ',$where).' ORDER BY e.expense_date DESC');$s->execute($p);return $s->fetchAll();}}
